CREATE DATABASE IF NOT EXISTS supermarket_db;
USE supermarket_db;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,username VARCHAR(50) NOT NULL UNIQUE,email VARCHAR(120) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('employee','customer') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customers(customer_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,phone VARCHAR(25),address VARCHAR(255),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE employees(employee_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,employee_number VARCHAR(30) NOT NULL UNIQUE,department VARCHAR(80),phone VARCHAR(25),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,product_name VARCHAR(120) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE purchases(id INT AUTO_INCREMENT PRIMARY KEY,invoice_number VARCHAR(40) NOT NULL UNIQUE,customer_id INT NOT NULL,total DECIMAL(10,2) NOT NULL,purchased_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(id));
CREATE TABLE purchase_items(id INT AUTO_INCREMENT PRIMARY KEY,purchase_id INT NOT NULL,product_id INT NOT NULL,product_name VARCHAR(120) NOT NULL,price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL,subtotal DECIMAL(10,2) NOT NULL,FOREIGN KEY(purchase_id) REFERENCES purchases(id),FOREIGN KEY(product_id) REFERENCES products(id));
